CREATE TABLE prep_recipes (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, updated_at DATETIME(6) NOT NULL);
CREATE TABLE recipe_ingredients (recipe_id BIGINT NOT NULL, inventory_id BIGINT NOT NULL, quantity_base DECIMAL(20,6) NOT NULL, input_unit VARCHAR(20) NOT NULL, PRIMARY KEY(recipe_id,inventory_id), FOREIGN KEY(recipe_id) REFERENCES prep_recipes(id), FOREIGN KEY(inventory_id) REFERENCES inventory_items(id), CHECK(quantity_base>0));
CREATE TABLE meal_plans (id BIGINT AUTO_INCREMENT PRIMARY KEY, recipe_id BIGINT NOT NULL, meal_date DATE NOT NULL, portions INT NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(recipe_id) REFERENCES prep_recipes(id), CHECK(portions>0 AND portions<=100000), INDEX(meal_date));
CREATE TABLE planning_buffers (inventory_id BIGINT NOT NULL, meal_date DATE NOT NULL, quantity_base DECIMAL(20,6) NOT NULL DEFAULT 0, PRIMARY KEY(inventory_id,meal_date), FOREIGN KEY(inventory_id) REFERENCES inventory_items(id), CHECK(quantity_base>=0));
